using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates multi-reference inter decode on a real four-frame AV1/IVF clip (generated by aomenc): the
/// later inter frames predict their blocks from several different reference names (LAST, GOLDEN and
/// ALTREF), which resolve to different previously decoded frames through the reference store's slot
/// mapping. Every decoded frame's luma and chroma are compared against dav1d's decoded output.
/// </summary>
public class Av1MultiReferenceDecodeTests
{
    private const string ClipIvfBase64 =
        "";

    private static readonly string[] Dav1dLumaBase64 = [
        "",
        "",
        "",
        ""
    ];

    private static readonly string[] Dav1dUBase64 = [
        "",
        "",
        "",
        ""
    ];

    private static readonly string[] Dav1dVBase64 = [
        "",
        "",
        "",
        ""
    ];

    [Fact]
    public void DecodeAllFrames_FourFrames_MatchDav1d()
    {
        using MemoryStream stream = new(Convert.FromBase64String(ClipIvfBase64));
        List<Av1TileDecoder> frames = Av1DecoderCore.DecodeAllFrames(stream);

        Assert.Equal(4, frames.Count);
        for (int i = 0; i < frames.Count; i++)
        {
            AssertPlaneMatches(frames[i].Luma.Samples, Dav1dLumaBase64[i], $"frame {i} luma");
            AssertPlaneMatches(frames[i].ChromaU.Samples, Dav1dUBase64[i], $"frame {i} chroma U");
            AssertPlaneMatches(frames[i].ChromaV.Samples, Dav1dVBase64[i], $"frame {i} chroma V");
        }
    }

    private static void AssertPlaneMatches(ReadOnlySpan<ushort> actual, string expectedBase64, string planeName)
    {
        byte[] expected = Convert.FromBase64String(expectedBase64);
        int exact = 0;
        int maxDiff = 0;
        for (int i = 0; i < expected.Length; i++)
        {
            int diff = Math.Abs(actual[i] - expected[i]);
            maxDiff = Math.Max(maxDiff, diff);
            Assert.True(diff <= 2, $"{planeName} sample {i}: got {actual[i]}, dav1d {expected[i]}.");
            if (actual[i] == expected[i])
            {
                exact++;
            }
        }

        Assert.True(exact >= expected.Length * 90 / 100, $"Only {exact}/{expected.Length} {planeName} samples matched exactly (maxDiff {maxDiff}).");
    }
}
